define('APP_ROOT', '..'); require __DIR__ . '/../includes/auth.php'; require_role('admin'); require __DIR__ . '/../config/database.php'; require __DIR__ . '/../includes/functions.php';
$id = isset($_GET['id']) ? (int) $_GET['id'] : 0; $stmt = mysqli_prepare($koneksi, 'SELECT * FROM users WHERE id_user=?'); mysqli_stmt_bind_param($stmt, 'i', $id); mysqli_stmt_execute($stmt); $user = mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); if (!$user || $user['role'] == 'admin') { set_flash('danger', 'Data anggota tidak ditemukan.'); header('Location: anggota.php'); exit; }
