$page_title='Edit Anggota';require __DIR__.'/../includes/header.php'; ?><div class="section-head"><div><p class="eyebrow">DATA ANGGOTA</p><h2>Edit anggota</h2></div><a class="btn secondary" href="user_detail.php?id=<?=$id?>">Kembali</a></div><?php foreach($errors as $error){?><div class="alert danger"><?=e($error)?></div><?php }?><form class="panel form-stack member-form" method="post"><label>Nama lengkap<input name="nama_lengkap" value="<?=e($user['nama_lengkap'])?>" required></label><label>Username<input name="username" value="<?=e($user['username'])?>" required></label><label>Email<input type="email" name="email" value="<?=e($user['email'])?>" required></label><label>No. telepon<input name="no_telepon" value="<?=e($user['no_telepon'])?>"></label><label>Password baru <small>Kosongkan bila tidak diubah.</small><input type="password" name="password"></label><button class="btn primary">Simpan perubahan</button></form><?php require __DIR__.'/../includes/footer.php'; ?>
